script.code:
/* ===================================================================
   UTILS.JS - RECONSTRUIDO DESDE CERO (PATRÓN HEADER)
   - Utilidades limpias para manipulación del DOM y datos
   - Compatible con proxies de atvise
   =================================================================== */

if (typeof EquiposGlobals === 'undefined') { var EquiposGlobals = {}; }
EquiposGlobals.UTILS = {};

// Helper para creación de elementos (Patrón Header)
// Helper para creación de elementos (Patrón Header Robust)
EquiposGlobals.UTILS.x = function (a, b) {
    var tag = (typeof a === "string") ? a : b;
    if (!tag) return null;
    var tagL = tag.toLowerCase();

    // Prefer passed doc, fallback to global document
    var d = (typeof a === "object" && a !== null && a.createElement) ? a : document;

    // 1. Try SVG creation (Namespaced)
    if (["svg", "path", "circle", "g", "rect", "text", "line", "image", "linearGradient", "stop", "defs", "tspan"].indexOf(tagL) >= 0) {
        try {
            return d.createElementNS("http://www.w3.org/2000/svg", tagL);
        } catch (e) {
            // If proxy fails, try global document
            try { return document.createElementNS("http://www.w3.org/2000/svg", tagL); } catch (ex) { }
        }
    }

    // 2. Try HTML creation
    try {
        return d.createElement(tagL);
    } catch (e) {
        // "Illegal invocation" or proxy error -> Try NS
        try {
            return d.createElementNS("http://www.w3.org/1999/xhtml", tagL);
        } catch (e2) {
            // Final fallback: Global document
            try {
                return document.createElement(tagL);
            } catch (e3) {
                return null;
            }
        }
    }
};

// Helper para estilos
EquiposGlobals.UTILS.setStyles = function (el, styles) {
    if (!el || !styles) return;
    for (var k in styles) {
        if (Object.prototype.hasOwnProperty.call(styles, k)) {
            el.style[k] = styles[k];
        }
    }
};

// Históricos (Caudalimetros logic adapted)
EquiposGlobals.UTILS.readHist = function (node, t1, t2, cb) {
    var sPath = (node.indexOf("s=") >= 0) ? node.split("s=")[1] : node;

    function fixTs(ts) {
        var n = Number(ts);
        return (n && n < 1e12) ? (n * 1000) : n;
    }

    // PASS 1: Get the state precisely before t1 to have a starting point
    var fBefore = {
        type: ["v:1"],
        address: ["g:" + sPath],
        select: ["v:timestamp", "v:value"],
        timestamp: ["n:<" + t1],
        order: ["v:desc"],
        numrows: ["v:1"]
    };

    webMI.data.queryFilter(fBefore, function (resB) {
        var allPts = [];
        if (resB && resB.result && resB.result.length > 0) {
            allPts.push({ t: t1, v: resB.result[0].value, initial: true });
        }

        // PASS 2: Get all transitions within the range recursively
        function fetchRange(currentFrom) {
            var fRange = {
                type: ["v:1"],
                address: ["g:" + sPath],
                select: ["v:timestamp", "v:value"],
                timestamp: ["n:>=" + Math.floor(currentFrom) + "<=" + t2],
                order: ["v:asc"],
                numrows: ["v:10000"]
            };

            webMI.data.queryFilter(fRange, function (resR) {
                var rows = (resR && resR.result) || [];
                if (rows.length > 0) {
                    for (var i = 0; i < rows.length; i++) {
                        var r = rows[i];
                        allPts.push({ t: fixTs(r.timestamp), v: r.value });
                    }

                    if (rows.length >= 10000) {
                        var lastT = allPts[allPts.length - 1].t;
                        fetchRange(lastT > currentFrom ? lastT : currentFrom + 1);
                    } else {
                        allPts.sort(function (a, b) { return a.t - b.t; });
                        if (cb) cb(allPts);
                    }
                } else {
                    allPts.sort(function (a, b) { return a.t - b.t; });
                    if (cb) cb(allPts);
                }
            });
        }
        fetchRange(t1);
    });
};

// Adición segura al DOM
EquiposGlobals.UTILS.safeAppend = function (p, c) {
    if (!p || !c) return;
    try {
        p.appendChild(c);
    } catch (e) {
        try {
            var d = p.ownerDocument || document;
            if (p === d.body) d.body.appendChild(c);
        } catch (e2) { }
    }
};

// Limpieza de contenedor
EquiposGlobals.UTILS.clear = function (el) {
    if (!el) return;
    while (el.firstChild) {
        try {
            el.removeChild(el.firstChild);
        } catch (e) {
            el.innerHTML = "";
            break;
        }
    }
};

// Subscripciones simplificadas
EquiposGlobals.UTILS.addSub = function (addr, cb, subs) {
    try {
        var id = webMI.data.subscribe(addr, cb);
        if (subs && subs.push) subs.push(id);
        return id;
    } catch (e) { return null; }
};

EquiposGlobals.UTILS.log = function () {
    // console.log.apply(console, arguments); // Disabled for production
};

// ===================================================================
// DATA MANIPULATION (Pattern Header)
// ===================================================================

EquiposGlobals.UTILS.groupData = function (series, intervalMs) {
    if (!series || !Array.isArray(series)) return [];
    var buckets = {};
    series.forEach(function (p) {
        var bucketKey = Math.floor(p.t / intervalMs) * intervalMs;
        if (!buckets[bucketKey] || p.t > buckets[bucketKey].lastT) {
            buckets[bucketKey] = { t: bucketKey, v: p.v, lastT: p.t };
        }
    });

    return Object.keys(buckets)
        .sort(function (a, b) { return +a - +b; })
        .map(function (k) { return { t: buckets[k].t, v: buckets[k].v }; });
};

// ===================================================================
// LEGACY CHART HELPERS (Required by Render.js)
// ===================================================================

// Inicializa el objeto _chart en la instancia de EquiposCard
EquiposGlobals.UTILS.chartInit = function (cardInstance) {
    if (!cardInstance) return;

    // Crear estructura de chart si no existe
    if (!cardInstance._chart) {
        cardInstance._chart = {
            ready: false,
            series: {
                sts: [],    // Estado ON/OFF
                freq: [],   // Frecuencia
                volt: [],   // Voltaje
                cur1: [],   // Corriente L1
                cur2: [],   // Corriente L2
                cur3: [],   // Corriente L3
                fp: []      // Factor de Potencia
            }
        };
    }

    // Cargar histórico inicial (8 horas por defecto)
    var now = Date.now();
    var from = now - (8 * 60 * 60 * 1000);
    cardInstance._loadAllHistoric = cardInstance._loadAllHistoric || function (hours) {
        var t2 = Date.now();
        var t1 = t2 - (hours * 60 * 60 * 1000);
        cardInstance._loadHistManual(t1, t2);
    };

    // Stub para carga manual
    if (!cardInstance._loadHistManual) {
        cardInstance._loadHistManual = function (t1, t2) {
            // Implementación básica: marcar como listo y redibujar
            cardInstance._chart.ready = true;
            if (cardInstance.elements && cardInstance.elements.chartLoading) {
                cardInstance.elements.chartLoading.style.display = 'none';
            }
            cardInstance._scheduleChartDraw();
        };
    }
};

// Renderiza el chart en canvas (modo legacy para tarjetas pequeñas)
EquiposGlobals.UTILS.chartDraw = function (cardInstance) {
    if (!cardInstance || !cardInstance.elements) return;

    var canvas = cardInstance.elements.chartCanvas;
    if (!canvas || !canvas.getContext) return; // Solo para canvas, no DIV

    var ctx = canvas.getContext('2d');
    if (!ctx) return;

    var w = canvas.width || 200;
    var h = canvas.height || 60;

    // Limpiar canvas
    ctx.clearRect(0, 0, w, h);

    // Verificar si hay datos
    if (!cardInstance._chart || !cardInstance._chart.ready || !cardInstance._chart.series) {
        ctx.fillStyle = '#64748b';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Sin datos', w / 2, h / 2);
        return;
    }

    // Dibujo básico de línea (frecuencia como ejemplo)
    var series = cardInstance._chart.series.freq || [];
    if (series.length < 2) return;

    var vals = series.map(function (p) { return p.v; });
    var min = Math.min.apply(null, vals);
    var max = Math.max.apply(null, vals);
    var range = max - min || 1;

    ctx.beginPath();
    ctx.strokeStyle = '#1e88e5';
    ctx.lineWidth = 1.5;

    for (var i = 0; i < series.length; i++) {
        var x = (i / (series.length - 1)) * w;
        var y = h - ((series[i].v - min) / range) * h;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.stroke();
};

// Adjunta eventos de hover al chart
EquiposGlobals.UTILS.attachChartHover = function (cardInstance) {
    if (!cardInstance || !cardInstance.elements) return;

    var canvas = cardInstance.elements.chartCanvas;
    var overlay = cardInstance.elements.chartOverlay;
    var tip = cardInstance.elements.chartTip;

    if (!canvas || !overlay || !tip) return;

    // Stub básico: no hacer nada en tarjetas pequeñas
    // El hover completo solo funciona en dashboard fullscreen (buildEquipmentChart)
    canvas.onmousemove = null;
    canvas.onmouseleave = null;
};

// ===================================================================
// CHART RENDERING ENGINE (Patrón Header Dashboard)
// ===================================================================


// Configuración de series para gráficos
EquiposGlobals.UTILS.SERIES_CONFIG = {
    sts: { color: '#22c55e', label: 'Estado', unit: '', type: 'area', yMin: 0, yMax: 1 },
    freq: { color: '#1e88e5', label: 'Frecuencia', unit: 'Hz', type: 'line' },
    cur1: { color: '#6a1b9a', label: 'Corriente L1', unit: 'A', type: 'line' },
    cur2: { color: '#7b1fa2', label: 'Corriente L2', unit: 'A', type: 'line' },
    cur3: { color: '#8e24aa', label: 'Corriente L3', unit: 'A', type: 'line' },
    fp: { color: '#7c3aed', label: 'Factor de Potencia', unit: '', type: 'line' },
    volt: { color: '#0ea5e9', label: 'Voltaje', unit: 'V', type: 'line' }
};

/**
 * Construye y renderiza un gráfico multi-series SVG para el dashboard de equipos
 * @param {Document} doc - Documento (puede ser proxy de atvise)
 * @param {HTMLElement} container - Contenedor donde se dibujará el SVG
 * @param {Object} seriesMap - Mapa de series {sts: [{t, v}], freq: [{t, v}], ...}
 * @param {Object} colors - Mapa de colores por serie (opcional, usa SERIES_CONFIG por defecto)
 */
EquiposGlobals.UTILS.buildEquipmentChart = function (doc, container, seriesMap, colors) {
    var U = EquiposGlobals.UTILS;
    if (!container) return;

    // Limpiar contenedor
    U.clear(container);

    var w = container.clientWidth || container.getBoundingClientRect().width || 800;
    var h = container.clientHeight || container.getBoundingClientRect().height || 400;
    var pad = 40;

    var SVG_NS = "http://www.w3.org/2000/svg";

    // Crear SVG principal
    var svg = doc.createElementNS(SVG_NS, "svg");
    svg.setAttribute("width", w);
    svg.setAttribute("height", h);
    svg.style.display = "block";
    svg.style.cursor = "crosshair";
    container.appendChild(svg);

    // Validar que hay datos
    var hasData = false;
    var allPoints = [];
    for (var key in seriesMap) {
        if (seriesMap[key] && seriesMap[key].length > 0) {
            hasData = true;
            allPoints = allPoints.concat(seriesMap[key]);
        }
    }

    if (!hasData || allPoints.length === 0) {
        var noDataText = doc.createElementNS(SVG_NS, "text");
        noDataText.textContent = "Sin datos disponibles";
        noDataText.setAttribute("x", w / 2);
        noDataText.setAttribute("y", h / 2);
        noDataText.setAttribute("text-anchor", "middle");
        noDataText.setAttribute("fill", "#64748b");
        noDataText.setAttribute("font-size", "16");
        noDataText.setAttribute("font-weight", "600");
        svg.appendChild(noDataText);
        return;
    }

    // Calcular dominio temporal (X-axis)
    var tMin = Infinity, tMax = -Infinity;
    for (var i = 0; i < allPoints.length; i++) {
        var t = allPoints[i].t;
        if (t < tMin) tMin = t;
        if (t > tMax) tMax = t;
    }
    var tRange = tMax - tMin || 1;

    // Calcular dominio de valores (Y-axis) con 10% headroom
    var vMin = Infinity, vMax = -Infinity;
    for (var key in seriesMap) {
        if (key === 'sts') continue; // Excluir estado del cálculo general
        var series = seriesMap[key];
        if (!series || !series.length) continue;
        for (var i = 0; i < series.length; i++) {
            var v = series[i].v;
            if (v < vMin) vMin = v;
            if (v > vMax) vMax = v;
        }
    }
    if (!isFinite(vMin)) vMin = 0;
    if (!isFinite(vMax)) vMax = 100;
    if (vMin === vMax) { vMin = 0; vMax = Math.max(1, vMax); }

    var vRange = vMax - vMin;
    var yMaxScaled = vMax + (vRange * 0.1); // 10% headroom
    var yMinScaled = Math.max(0, vMin - (vRange * 0.05));

    // Funciones de escalado
    function sx(t) {
        return pad + ((t - tMin) / tRange) * (w - 2 * pad);
    }
    function sy(v) {
        return h - pad - ((v - yMinScaled) / (yMaxScaled - yMinScaled)) * (h - 2 * pad);
    }
    function sySts(v) {
        // Estado: escala fija 0-1
        return h - pad - (v * (h - 2 * pad));
    }

    // --- DIBUJAR ÁREA DE ESTADO (fondo) ---
    if (seriesMap.sts && seriesMap.sts.length > 1) {
        var stsSeries = seriesMap.sts.slice().sort(function (a, b) { return a.t - b.t; });
        var pathData = "M" + sx(stsSeries[0].t) + "," + sySts(stsSeries[0].v);
        for (var i = 1; i < stsSeries.length; i++) {
            pathData += " L" + sx(stsSeries[i].t) + "," + sySts(stsSeries[i].v);
        }
        // Cerrar el área
        pathData += " L" + sx(stsSeries[stsSeries.length - 1].t) + "," + (h - pad);
        pathData += " L" + sx(stsSeries[0].t) + "," + (h - pad);
        pathData += " Z";

        var areaPath = doc.createElementNS(SVG_NS, "path");
        areaPath.setAttribute("d", pathData);
        areaPath.setAttribute("fill", "rgba(34, 197, 94, 0.15)");
        areaPath.setAttribute("stroke", "none");
        svg.appendChild(areaPath);
    }

    // --- DIBUJAR LÍNEAS DE SERIES ---
    var seriesKeys = ['freq', 'volt', 'cur1', 'cur2', 'cur3', 'fp'];
    for (var k = 0; k < seriesKeys.length; k++) {
        var key = seriesKeys[k];
        if (!seriesMap[key] || seriesMap[key].length < 2) continue;

        var series = seriesMap[key].slice().sort(function (a, b) { return a.t - b.t; });
        var config = U.SERIES_CONFIG[key] || {};
        var color = (colors && colors[key]) || config.color || '#666';

        var pathData = "M" + sx(series[0].t) + "," + sy(series[0].v);
        for (var i = 1; i < series.length; i++) {
            pathData += " L" + sx(series[i].t) + "," + sy(series[i].v);
        }

        var linePath = doc.createElementNS(SVG_NS, "path");
        linePath.setAttribute("d", pathData);
        linePath.setAttribute("stroke", color);
        linePath.setAttribute("stroke-width", "2.5");
        linePath.setAttribute("fill", "none");
        linePath.setAttribute("stroke-linejoin", "round");
        linePath.setAttribute("stroke-linecap", "round");
        svg.appendChild(linePath);
    }

    // --- ELEMENTOS INTERACTIVOS (Tooltip) ---
    var vLine = doc.createElementNS(SVG_NS, "line");
    vLine.setAttribute("y1", pad);
    vLine.setAttribute("y2", h - pad);
    vLine.setAttribute("stroke", "#94a3b8");
    vLine.setAttribute("stroke-width", "2");
    vLine.setAttribute("opacity", "0");
    svg.appendChild(vLine);

    // Dots para cada serie
    var dots = {};
    for (var key in U.SERIES_CONFIG) {
        if (key === 'sts') continue;
        var config = U.SERIES_CONFIG[key];
        var color = (colors && colors[key]) || config.color;
        var dot = doc.createElementNS(SVG_NS, "circle");
        dot.setAttribute("r", "5");
        dot.setAttribute("fill", "#fff");
        dot.setAttribute("stroke", color);
        dot.setAttribute("stroke-width", "2.5");
        dot.setAttribute("opacity", "0");
        svg.appendChild(dot);
        dots[key] = dot;
    }

    // Tooltip background
    var tipBg = doc.createElementNS(SVG_NS, "rect");
    tipBg.setAttribute("rx", "8");
    tipBg.setAttribute("ry", "8");
    tipBg.setAttribute("fill", "rgba(15, 23, 42, 0.95)");
    tipBg.setAttribute("stroke", "rgba(255,255,255,0.15)");
    tipBg.setAttribute("stroke-width", "1");
    tipBg.style.display = "none";
    svg.appendChild(tipBg);

    // Tooltip text
    var tipText = doc.createElementNS(SVG_NS, "text");
    tipText.setAttribute("fill", "#ffffff");
    tipText.setAttribute("font-size", "13");
    tipText.setAttribute("font-weight", "500");
    tipText.style.display = "none";
    svg.appendChild(tipText);

    // Función para formatear timestamp
    function formatTime(ts) {
        var d = new Date(ts);
        var day = ('0' + d.getDate()).slice(-2);
        var mon = ('0' + (d.getMonth() + 1)).slice(-2);
        var hrs = ('0' + d.getHours()).slice(-2);
        var min = ('0' + d.getMinutes()).slice(-2);
        return day + "/" + mon + " " + hrs + ":" + min;
    }

    // Interacción: mousemove
    svg.onmousemove = function (e) {
        var rect = svg.getBoundingClientRect();
        var mx = e.clientX - rect.left;

        // Calcular timestamp aproximado
        var ratio = Math.max(0, Math.min(1, (mx - pad) / (w - 2 * pad)));
        var tHover = tMin + (ratio * tRange);

        // Encontrar punto más cercano en cada serie
        var closestPoints = {};
        var hasAnyPoint = false;

        for (var key in seriesMap) {
            var series = seriesMap[key];
            if (!series || series.length === 0) continue;

            var minDist = Infinity;
            var closestPoint = null;
            for (var i = 0; i < series.length; i++) {
                var dist = Math.abs(series[i].t - tHover);
                if (dist < minDist) {
                    minDist = dist;
                    closestPoint = series[i];
                }
            }
            if (closestPoint) {
                closestPoints[key] = closestPoint;
                hasAnyPoint = true;
            }
        }

        if (!hasAnyPoint) return;

        // Obtener el timestamp del punto más cercano (usar primera serie no vacía)
        var refPoint = closestPoints.freq || closestPoints.volt || closestPoints.cur1;
        if (!refPoint) return;

        // Posicionar línea vertical
        var x = sx(refPoint.t);
        vLine.setAttribute("x1", x);
        vLine.setAttribute("x2", x);
        vLine.setAttribute("opacity", "1");

        // Posicionar dots
        for (var key in dots) {
            if (closestPoints[key]) {
                var dot = dots[key];
                var yVal = key === 'sts' ? sySts(closestPoints[key].v) : sy(closestPoints[key].v);
                dot.setAttribute("cx", x);
                dot.setAttribute("cy", yVal);
                dot.setAttribute("opacity", "1");
            } else {
                dots[key].setAttribute("opacity", "0");
            }
        }

        // Construir tooltip multi-línea
        tipText.innerHTML = "";
        var lineSpacing = 1.3;
        var lineNum = 0;

        // Fecha/hora
        var timeTspan = doc.createElementNS(SVG_NS, "tspan");
        timeTspan.setAttribute("x", "0");
        timeTspan.setAttribute("dy", "0");
        timeTspan.style.fill = "#fbbf24";
        timeTspan.style.fontWeight = "bold";
        timeTspan.textContent = formatTime(refPoint.t);
        tipText.appendChild(timeTspan);
        lineNum++;

        // Series
        var orderedKeys = ['sts', 'freq', 'volt', 'cur1', 'cur2', 'cur3', 'fp'];
        for (var k = 0; k < orderedKeys.length; k++) {
            var key = orderedKeys[k];
            if (!closestPoints[key]) continue;

            var config = U.SERIES_CONFIG[key] || {};
            var val = closestPoints[key].v;
            var formatted = val.toFixed(key === 'sts' ? 0 : (key === 'fp' ? 3 : 2));

            var tspan = doc.createElementNS(SVG_NS, "tspan");
            tspan.setAttribute("x", "0");
            tspan.setAttribute("dy", lineNum === 0 ? "0" : (lineSpacing + "em"));
            tspan.style.fill = config.color || "#fff";
            tspan.textContent = config.label + ": " + formatted + (config.unit ? " " + config.unit : "");
            tipText.appendChild(tspan);
            lineNum++;
        }

        tipText.style.display = "block";

        // Posicionar tooltip
        try {
            var bbox = tipText.getBBox();
            var bgPad = 12;
            var tooltipW = bbox.width + bgPad * 2;
            var tooltipH = bbox.height + bgPad * 2;

            // Posición X: centrado en cursor, ajustado a Bounds
            var tooltipX = Math.min(
                Math.max(mx - tooltipW / 2, pad),
                w - tooltipW - pad
            );

            // Posición Y: arriba del cursor, fija
            var tooltipY = pad + 10;

            tipBg.setAttribute("x", tooltipX);
            tipBg.setAttribute("y", tooltipY);
            tipBg.setAttribute("width", tooltipW);
            tipBg.setAttribute("height", tooltipH);
            tipBg.style.display = "block";

            tipText.setAttribute("x", tooltipX + bgPad);
            tipText.setAttribute("y", tooltipY + bgPad + 12);
        } catch (e) {
            // getBBox puede fallar en algunos contextos
        }
    };

    svg.onmouseleave = function () {
        vLine.setAttribute("opacity", "0");
        for (var key in dots) {
            dots[key].setAttribute("opacity", "0");
        }
        tipBg.style.display = "none";
        tipText.style.display = "none";
    };

    // --- EJES Y ETIQUETAS ---
    // Y-axis labels (max y min)
    var yTopLabel = doc.createElementNS(SVG_NS, "text");
    yTopLabel.setAttribute("x", w - pad + 5);
    yTopLabel.setAttribute("y", pad);
    yTopLabel.setAttribute("fill", "#64748b");
    yTopLabel.setAttribute("font-size", "11");
    yTopLabel.setAttribute("font-weight", "600");
    yTopLabel.textContent = yMaxScaled.toFixed(1);
    svg.appendChild(yTopLabel);

    var yBotLabel = doc.createElementNS(SVG_NS, "text");
    yBotLabel.setAttribute("x", w - pad + 5);
    yBotLabel.setAttribute("y", h - pad + 4);
    yBotLabel.setAttribute("fill", "#64748b");
    yBotLabel.setAttribute("font-size", "11");
    yBotLabel.setAttribute("font-weight", "600");
    yBotLabel.textContent = yMinScaled.toFixed(1);
    svg.appendChild(yBotLabel);

    // X-axis labels (inicio y fin)
    var xStartLabel = doc.createElementNS(SVG_NS, "text");
    xStartLabel.setAttribute("x", pad);
    xStartLabel.setAttribute("y", h - pad + 16);
    xStartLabel.setAttribute("fill", "#64748b");
    xStartLabel.setAttribute("font-size", "10");
    xStartLabel.textContent = formatTime(tMin);
    svg.appendChild(xStartLabel);

    var xEndLabel = doc.createElementNS(SVG_NS, "text");
    xEndLabel.setAttribute("x", w - pad);
    xEndLabel.setAttribute("y", h - pad + 16);
    xEndLabel.setAttribute("fill", "#64748b");
    xEndLabel.setAttribute("font-size", "10");
    xEndLabel.setAttribute("text-anchor", "end");
    xEndLabel.textContent = formatTime(tMax);
    svg.appendChild(xEndLabel);
};
